import numpy as np
from scipy.optimize import least_squares, curve_fit
raw=np.loadtxt('graphene.dat',delimiter='\t',dtype=str)
x=np.array([float(a.replace(',','.')) for a,b in raw])
y=np.array([float(b.replace(',','.')) for a,b in raw])
nu=1e7/x
o=np.argsort(nu); nu=nu[o]; y=y[o]; x=x[o]

def lor(nu,x0,g,A,off):
    return off + A*g**2/((nu-x0)**2+g**2)
def lor_lin(nu,x0,g,A,off,sl):
    return off + sl*(nu-x0) + A*g**2/((nu-x0)**2+g**2)
def gauss(nu,x0,s,A,off):
    return off + A*np.exp(-0.5*((nu-x0)/s)**2)

def fitwin(name, lo, hi, p0, model='lor', linear=False):
    m=(nu>=lo)&(nu<=hi)
    X=nu[m]; Y=y[m]
    if model=='lor':
        f=lor
        if linear:
            def res(p): return lor_lin(X,*p)-Y
            p0=[*p0,0.0]
        else:
            def res(p): return lor(X,*p)-Y
    else:
        f=gauss
        def res(p): return gauss(X,*p)-Y
    r=least_squares(res,p0,loss='soft_l1',f_scale=100)
    perr=None
    # bootstrap-ish covariance
    J=r.jac
    try:
        cov=np.linalg.inv(J.T@J)*(np.sum(r.fun**2)/(len(Y)-len(p0)))
        perr=np.sqrt(np.diag(cov))
    except Exception: pass
    rms=np.sqrt(np.mean(r.fun**2))
    print(f"{name} win[{lo},{hi}] {model}{'+lin' if linear else ''}: p={np.round(r.x,4)} err={None if perr is None else np.round(perr,4)} rms={rms:.2f}")
    return r.x

print('=== G in nu ===')
for win in [(1350,1800),(1400,1750),(1450,1720),(1480,1700),(1500,1680),(1520,1650)]:
    fitwin('G',*win,[1580,20,5000,6000],linear=False)
for win in [(1400,1750),(1450,1720),(1480,1700)]:
