import numpy as np
from scipy.optimize import least_squares
from scipy.special import wofz
raw=np.loadtxt('graphene.dat',delimiter='\t',dtype=str)
x=np.array([float(a.replace(',','.')) for a,b in raw]); y=np.array([float(b.replace(',','.')) for a,b in raw])
nu=1e7/x; o=np.argsort(nu); nu=nu[o]; y=y[o]

def base(t,p,tc): return sum(p[k]*(t-tc)**k for k in range(len(p)))
def lor(t,x0,g,A): return A*g**2/((t-x0)**2+g**2)
def gau(t,x0,s,A): return A*np.exp(-0.5*((t-x0)/s)**2)
def pvoigt(t,x0,w,A,eta):
    # w is HWHM-ish; use gaussian sigma=w/sqrt(2ln2)? use fwhm w for both
    s=w/(2*np.sqrt(2*np.log(2))); g=w/2
    return A*(eta*g**2/((t-x0)**2+g**2)+(1-eta)*np.exp(-0.5*((t-x0)/s)**2))

def fit(lo,hi,x0,g,A,kind,deg=1):
    m=(nu>=lo)&(nu<=hi); t=nu[m]; Y=y[m]; tc=x0
    def fun(p):
        x0=p[0]; w=p[1]; A=p[2]; bp=p[3:]
        if kind=='lor': peak=lor(t,x0,w,A)
        elif kind=='gau': peak=gau(t,x0,w,A)
        else:
            eta=p[3]; bp=p[4:]; peak=pvoigt(t,x0,w,A,eta)
        return base(t,bp,tc)+peak-Y
    edge=((t<tc-3*abs(g))|(t>tc+3*abs(g)))
    bp=np.polyfit(t[edge]-tc,Y[edge],deg)[::-1]
    if kind=='pvoigt':
        p0=[x0,g,A,0.5,*bp]
    else:
        p0=[x0,g,A,*bp]
    r=least_squares(fun,p0,loss='soft_l1',f_scale=100,max_nfev=50000)
    print(kind,lo,hi,'rms',round(np.sqrt(np.mean(r.fun**2)),2),'p',np.round(r.x[:4] if kind=='pvoigt' else r.x[:3],3))
for kind in ['lor','gau','pvoigt']:
    fit(1450,1720,1580.5,8.5,8300,kind,deg=1)
for kind in ['lor','gau','pvoigt']:
    fit(2450,2900,2670,17,12500,kind,deg=2)
